def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    result = []
    for candidate in classes:
        if candidate is None:
            continue
        if not isinstance(candidate, type):
            raise TypeError(f"{candidate!r} is not a class")

        # Skip if candidate is already covered by an existing class in result
        if any(issubclass(existing, candidate) for existing in result):
            continue

        # Remove any existing class that is a subclass of candidate
        result = [existing for existing in result if not issubclass(candidate, existing)]

        # Append candidate if not already present (duplicates)
        if candidate not in result:
            result.append(candidate)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    # Ensure iterable
    try:
        iter(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of class objects")
    seen = set()
    result_rev = []
    for cls in reversed(list(classes)):
        if not isinstance(cls, type):
            raise TypeError(f"element {cls!r} is not a class")
        # Skip if any already kept class is a subclass of this candidate
        if any(issubclass(other, cls) for other in seen):
            continue
        seen.add(cls)
        result_rev.append(cls)
    return list(reversed(result_rev))

