    except AttributeError:
        # The object doesn't hold error indices; return an empty array
        return np.array([], dtype=int)

    # If no error mapping for this coordinate, return empty array
    try:
        idx = err_mapping[coord_name]
    except KeyError:
        return np.array([], dtype=int)

    # Ensure the retrieved indices are array-like
    if isinstance(idx, (list, np.ndarray)):
        return np.asarray(idx, dtype=int)
    else:
        raise ValueError(f"Error indices for coordinate '{coord_name}' must be list or array, got {type(idx).__name__}")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure the coordinate exists in the object's variables
    if coord_name not in getattr(self, "_variables", {}):
        raise KeyError(
            f"Coordinate '{coord_name}' not found in available variables."
        )
    var = self._variables[coord_name]

    # Attempt to locate the error array
    err = None
    # Common attribute names for error information
    if hasattr(var, "err"):
        err = var.err
    elif hasattr(var, "errors"):
        err = var.errors
    elif hasattr(var, "attrs"):
        err = var.attrs.get("err", None) or var.attrs.get("errors", None)

    # If no error information is present, return an empty list
    if err is None:
        return []

    # Convert to a NumPy array for consistent handling
    try:
        err_arr = np.asarray(err)
    except Exception as exc:  # pragma: no cover
        raise ValueError(
            f"Error data for coordinate '{coord_name}' could not be "
            f"converted to an array: {exc}"
        )

    # Determine indices of valid error values
    if err_arr.ndim == 0:
        # Scalar error: consider index 0 if non-zero
        return [0] if err_arr.item() != 0 else []

    # Use a mask: error values that are not NaN and non-zero
    with np.errstate(all="ignore"):
        mask = ~np.isnan(err_arr) & (err_arr != 0)

    # Flatten to 1D if necessary
    if mask.ndim > 1:
        mask = mask.ravel()

    indices = np.where(mask)[0]
    return indices.tolist()

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Attempt to fetch the error array for the specified coordinate.
        try:
            err_arr = np.asarray(self.errors[coord_name])
        except (AttributeError, KeyError, TypeError):
            # If the attributes don't exist or the key isn't present, return an empty list.
            return []

        # If the array is empty return empty list.
        if err_arr.size == 0:
            return []

        # Create a mask for valid error entries.
        # 1) For boolean arrays use the truth value directly.
        # 2) For numeric arrays consider non‑nan and positive values as valid error indices.
        if err_arr.dtype.kind in {'b', 'bool'}:
            mask = err_arr
        else:
            mask = ~np.isnan(err_arr) & (err_arr > 0)

        # Return the indices where the mask is True as a plain list.
        return np.where(mask)[0].tolist()

