def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    coord_arr = np.asarray(coord)
    if coord_arr.ndim != 1 or coord_arr.size != len(self.edges):
        raise ValueError(
            f"coord must be a 1‑D array of length {len(self.edges)}, "
            f"got {coord_arr.shape}"
        )

    indices = []
    for dim, edge in enumerate(self.edges):
        bin_idx = np.searchsorted(edge, coord_arr[dim], side='right') - 1
        # Valid indices are 0 .. len(edge)-2
        if bin_idx < 0 or bin_idx >= (edge.size - 1):
            # Coordinate outside valid range; ignore this point
            return
        indices.append(bin_idx)

    try:
        self.values[tuple(indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to fill histogram: {exc}") from exc

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure coord is an array of coordinates
    coord = np.atleast_1d(coord)

    # Determine the dimensionality of the histogram
    ndim = len(self.edges)

    # If coord is a scalar but histogram is multi‑dimensional, reject
    if coord.size == 1 and ndim > 1:
        raise ValueError(
            f"Expected a coordinate of length {ndim} but got a scalar."
        )

    # If coord is a vector and histogram is 1‑D, convert to scalar
    if ndim == 1:
        coord = coord[0]

    # Check dimension match
    if ndim == 1 and np.isscalar(coord) is False:
        raise ValueError(
            f"Expected a scalar coordinate for a 1‑D histogram, got {coord!r}"
        )
    if ndim > 1 and len(coord) != ndim:
        raise ValueError(
            f"Expected {ndim} coordinates but got {len(coord)}: {coord!r}"
        )

    # Find bin indices for each coordinate
    indices = []
    for i, c in enumerate(coord) if ndim > 1 else [coord]:
        edges = self.edges[i] if ndim > 1 else self.edges
        if c < edges[0] or c >= edges[-1]:
            # Coordinate lies outside the histogram bounds; ignore
            return
        # Find bin index using searchsorted
        idx = np.searchsorted(edges, c, side='right') - 1
        indices.append(idx)

    # Increment the bin count (handle scalar vs. array indexing)
    if ndim == 1:
        self.data[indices[0]] += weight
    else:
        self.data[tuple(indices)] += weight

