        prior_model = getattr(prior, "model", None)
        if cur_model is not None and prior_model is not None and cur_model != prior_model:
            errors.append(f"Model mismatch: current model {cur_model} vs prior model {prior_model}")
    except Exception:
        # If either side lacks a model attribute we ignore this check
        pass

    # Commonly relevant attributes that should match between versions
    attributes_to_compare = ["species", "reactions", "stoichiometry", "propensities"]
    for attr in attributes_to_compare:
        try:
