        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type check: prior should be the same validator type as self
        if not isinstance(prior, self.__class__):
            raise TypeError(
                f"Prior must be an instance of {self.__class__.__name__}, "
                f"got {type(prior).__name__}"
            )

        # Ensure the inventories expose a ``version`` attribute
        try:
            current_version = getattr(self, "version")
            prior_version = getattr(prior, "version")
        except AttributeError as exc:
            raise AttributeError(
                "Both inventory objects must expose a 'version' attribute"
            ) from exc

        # The prior version must be older (strictly less) than the current one
        if prior_version >= current_version:
            raise ValueError(
                f"Prior version {prior_version} is not older than "
                f"current version {current_version}"
            )

        # Common inventory sections that should be preserved across versions.
        # If an attribute exists in the prior inventory but is missing from the
        # current one, the current inventory cannot be considered a valid
        # successor.
        section_names = [
            "variables",
            "parameters",
            "functions",
            "constraints",
            "equations",
            "operators",
        ]

        for name in section_names:
            current_section = getattr(self, name, None)
            prior_section = getattr(prior, name, None)
            if prior_section is None:
                continue
            if current_section is None:
                raise ValueError(
                    f"Current inventory does not contain the section '{name}' "
                    f"present in the prior inventory"
                )
            # Convert to sets to compare items
            try:
                current_set = set(current_section)
            except TypeError:
                # Non-hashable items can't be put into a set; fall back to list comparison
                current_set = {tuple(x.items()) if hasattr(x, "items") else x for x in current_section}
            try:
                prior_set = set(prior_section)
            except TypeError:
                prior_set = {tuple(x.items()) if hasattr(x, "items") else x for x in prior_section}

            missing = prior_set - current_set
            if missing:
                raise ValueError(
                    f"Prior inventory contains items in section '{name}' "
                    f"that are missing in the current inventory: {missing}"
                )

        # If all checks pass, the prior version is considered valid.
        return True  # Explicitly return True to signal success.

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object and both self
    and prior inventories are assumed to have been checked for internal consistency.
    """
    # Make sure the incoming prior is an InventoryValidator of the same type.
    if not isinstance(prior, type(self)):
