def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
        Mapping of package base names (derived from XML filenames) to lists of
        relative file names that share that base name.
    """
    import os
    result = {}
    try:
        if not os.path.isdir(folder):
            raise ValueError(f"Provided path is not a directory: {folder}")

        # Build temporary mapping from basename to list of files
        temp = {}
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue
            base, ext = os.path.splitext(entry)
            temp.setdefault(base, []).append(entry)

        # Keep only groups that contain an .xml file
        for base, files in temp.items():
            xml_file = None
            for f in files:
                if f.lower().endswith(".xml"):
                    xml_file = f
                    break
            if xml_file:
                result[base] = files

    except Exception as exc:
        # Log the exception or handle as needed; re-raise for visibility
        raise RuntimeError(f"Unable to explore folder '{folder}': {exc}") from exc

    return result

