def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path` as a list of paths within the zip archive."""
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Filter out directory entries (names ending with '/')
            files = [name for name in zf.namelist() if not name.endswith("/") and not name.endswith(".pyc")]
            return files
    except (FileNotFoundError, zipfile.BadZipFile):
        # Return an empty list if the zip file can't be read
        return []

