def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis:
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1,
    suppl, suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Cópia de listas de palavras chave usadas para identificar suplementos
    SUPPL_KEYWORDS = {
        'sup', 'suppl', 'supp', 's',  # formas abreviadas / variações
        'spe', 'sp'                   # abreviações possivelmente usadas
    }

    # Extrai o texto contido no elemento 'issue'
    if issue is None:
        return (None, None)

    if hasattr(issue, 'text'):
        text = issue.text or ''
    else:
        # Se não for um elemento, usa a sua representação em string
        text = str(issue) or ''
    text = text.strip()
    if not text:
        return (None, None)

    # Tokeniza separando numéricos (permitindo hífens) e sequências alfabéticas
    tokens = re.findall(r'\d+(?:-\d+)?|[A-Za-z]+', text)
    if not tokens:
        return (None, None)

    used_as_suppl = set()
    suppl_value = None
    keyword_present = False

    # Identifica palavras chave de suplemento e, se houver número logo após,
    # considera-o como valor de suplemento; caso contrário, assume 1.
    for i, tok in enumerate(tokens):
        tok_lower = tok.lower()
        if tok_lower in SUPPL_KEYWORDS:
            keyword_present = True
            # Verifica se o token imediatamente posterior é numérico
            if i + 1 < len(tokens):
                next_tok = tokens[i + 1]
                if re.fullmatch(r'\d+(?:-\d+)?', next_tok):
                    suppl_value = next_tok
                    used_as_suppl.add(i + 1)
                    continue
            # Se não houver número depois do token, supõe-se suplemento 1
            suppl_value = '1'

    # Determina o número principal: primeiro token numérico que não foi
    # usado como suplemento
    number_value = None
    for idx, tok in enumerate(tokens):
        if re.fullmatch(r'\d+(?:-\d+)?', tok) and idx not in used_as_suppl:
            number_value = tok
            break

    # Se não houver número e houver palavra chave, ainda assim pode se
    # tratar de número suplementar apenas
    if number_value is None:
        # nenhum número encontrado fora dos suplementares
        pass

    # Se nenhum suplemento foi detectado explicitamente, mas há palavra
    # chave, presume suplemento 1
    if suppl_value is None and keyword_present:
        suppl_value = '1'

    return (number_value, suppl_value)

