def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Prepare the command list
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, list):
        raise TypeError("'commands' must be a string or a list of strings")
    if isinstance(args, list):
        cmd_list = commands + args
    else:
        cmd_list = commands + [args]

    # Optional verbosity
    if verbose:
        print("Executing:", " ".join(cmd_list))

    try:
        # Run the command, capturing output
        proc = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
            text=True,
            check=True
        )
        return proc.stdout
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {commands[0]}") from e
    except subprocess.CalledProcessError as e:
        stderr_msg = e.stderr if e.stderr else ""
        raise RuntimeError(
            f"Command '{' '.join(cmd_list)}' failed with exit code {e.returncode}"
            + (f"\nStderr: {stderr_msg}" if not hide_stderr else "")
        ) from e
    except Exception as ex:
        raise RuntimeError(f"Error running command '{' '.join(cmd_list)}': {ex}") from ex

