            raise ValueError(f"Cannot parse numeric version: {ver}")
        new_num = num + 1
        # Preserve original zero padding
        if ver[0] == '0' and len(ver) > 1:
            return str(new_num).zfill(len(ver))
        return str(new_num)
    # Handle versions with prefixes (e.g., 'v001' or 'rev10')
    # Find the trailing numeric part
    import re
    m = re.search(r'(?P<prefix>.*?)(?P<number>\d+)$', ver)
    if not m:
        # No numeric part found; cannot increment
        raise ValueError(f"No numeric suffix found in version: {ver}")
    prefix = m.group('prefix')
    number = m.group('number')
    try:
        new_num = int(number) + 1
    except ValueError:
        raise ValueError(f"Cannot parse numeric part in version: {ver}")
    # Preserve zero padding of the numeric suffix
    new_number = str(new_num).zfill(len(number))
    return f"{prefix}{new_number}"

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not version:
            return ""
        parts = version.split(".")
        # Find the rightmost numeric component and increment it
        for i in range(len(parts) - 1, -1, -1):
            comp = parts[i]
            if comp.isdigit():
                num_len = len(comp)
                new_val = str(int(comp) + 1)
                # Preserve leading zeros if originally present and more than one digit
                if comp.startswith("0") and num_len > 1:
                    new_val = new_val.zfill(num_len)
                parts[i] = new_val
                return ".".join(parts)
        # No numeric part found; return original
        return version
    except Exception:
        # In case of any error (e.g., invalid integers), return original
        return version

