    # If no bug ids passed, nothing to amend
    if not bug_ids:
        return params

    try:
        # Handle a single id
        if isinstance(bug_ids, (str, int)):
            params['id'] = str(bug_ids)
        # Handle iterable of ids
        elif isinstance(bug_ids, (list, tuple, set)):
            ids = [str(b) for b in bug_ids if b is not None]
            if not ids:
                return params
            if len(ids) == 1:
