def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    def is_mapping_node(node):
        return hasattr(node, "value") and isinstance(node.value, list)

    def merge_values(old_val, new_val):
        # If both nodes are mappings, merge them recursively
        if is_mapping_node(old_val) and is_mapping_node(new_val):
            merged_value = merge_mapping_lists(old_val.value + new_val.value)
            return type(old_val)(old_val.tag, merged_value)
        # Otherwise, the last one wins
        return new_val

    def merge_mapping_lists(lst):
        """
        Merge a list of (key_node, value_node) tuples where key_node is a ScalarNode
        and value_node is either a MappingNode or another node. This function
        preserves the order of first occurrence of each key and applies the same
        merging rules recursively.
        """
        merged = {}
        order = []
        for key_node, val_node in lst:
            key = (getattr(key_node, "tag", None), getattr(key_node, "value", None))
            if key in merged:
                merged[key] = merge_values(merged[key][1], val_node)
            else:
                merged[key] = (key_node, val_node)
                order.append(key_node)
        return [(merged[(getattr(k, "tag", None), getattr(k, "value", None))][0],
                 merged[(getattr(k, "tag", None), getattr(k, "value", None))][1]) for k in order]

    # Start with an empty merged list
    merged_list = []

    for key_node, val_node in nodes:
        key = (getattr(key_node, "tag", None), getattr(key_node, "value", None))
        # Search for existing key in merged_list
        found_index = None
        for idx, (k_node, _) in enumerate(merged_list):
            if (getattr(k_node, "tag", None), getattr(k_node, "value", None)) == key:
                found_index = idx
                break

        if found_index is not None:
            # Merge values
            existing_key_node, existing_val_node = merged_list[found_index]
            merged_val = merge_values(existing_val_node, val_node)
            merged_list[found_index] = (existing_key_node, merged_val)
        else:
            # Append new entry
            merged_list.append((key_node, val_node))

    return merged_list

