def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_results = {}
    all_remaining = []

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except SystemExit:
            # If parser fails (e.g. required arguments missing), treat as empty parse.
            namespace = argparse.Namespace()
            remaining = list(unparsed_arguments)
        parsed_results[name] = namespace
        all_remaining.append(remaining)

    if not all_remaining:
        # No subparsers provided
        return parsed_results, list(unparsed_arguments)

    # Determine arguments not claimed by any subparser (intersection of remaining lists)
    common_remaining_set = set(all_remaining[0])
    for rem in all_remaining[1:]:
        common_remaining_set.intersection_update(rem)

    # Preserve original order from the first remaining list
    remaining_unclaimed = [arg for arg in all_remaining[0] if arg in common_remaining_set]

    return parsed_results, remaining_unclaimed

