def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import Counter
    cumulative = Counter()
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        cumulative.update(d)
    return dict(cumulative)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not hasattr(dicts, '__iter__'):
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    for idx, d in enumerate(dicts):
        if not isinstance(d, dict):
            raise TypeError(f"Element #{idx} is not a dict: {repr(d)}")
        for key, val in d.items():
            # Accumulate numeric values; if not numeric, attempt to add (will raise if incompatible)
            result[key] = result.get(key, 0) + val
    return result

