def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    import argparse
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # action.option_strings may be empty for positional arguments
            for flag in action.option_strings:
                if flag:
                    flags.append(flag)
        return " ".join(flags)
    except Exception as exc:
        # In case parser is malformed or missing attributes
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser must not be None")

    # Verify that the parser has the expected interface
    try:
        actions = parser._actions
    except AttributeError as exc:
        raise TypeError("parser must be an argparse.ArgumentParser instance") from exc

    flags = []
    seen = set()
    for action in actions:
        # Each action should have an option_strings attribute
        try:
            opt_strings = action.option_strings
        except AttributeError:
            continue

        # Skip actions with no option strings (positional arguments)
        if not opt_strings:
            continue

        for opt in opt_strings:
            # Preserve the order of appearance and avoid duplicates
            if opt not in seen:
                seen.add(opt)
                flags.append(opt)

    return ' '.join(flags)

