def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # First, use sys.platform which is the standard way to detect the OS
        import sys
        if sys.platform == 'darwin':
            return True
    except Exception:
        # If for some reason sys.platform fails, fall back to os.uname()
        pass

    # Fallback: os.uname() may provide the system name 'Darwin' on macOS
    try:
        return os.uname().sysname == 'Darwin'
    except Exception:
        # Any failure implies we cannot confirm macOS
        return False

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems including macOS
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # Fallback to platform module if os.uname is not available (e.g., on Windows)
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False
    except Exception:
        return False

