def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    # Determine platform type
    plt = platform
    if platform == 'this':
        try:
            import sys
            plt = 0 if sys.platform.startswith('win') else 1
        except Exception:
            plt = 1  # default to POSIX
    args = []
    if plt == 1:  # POSIX
        # Simple regex: capture quoted or unquoted words
        token_re = re.compile(r'''"([^"]*)"|\'([^\']*)\'|(\S+)''')
        for m in token_re.finditer(s):
            if m.group(1) is not None:
                args.append(m.group(1))
            elif m.group(2) is not None:
                args.append(m.group(2))
            else:
                args.append(m.group(3))
    else:  # Windows
        i = 0
        length = len(s)
        while i < length:
            # Skip whitespace
            while i < length and s[i].isspace():
                i += 1
            if i >= length:
                break
            if s[i] == '"':
                i += 1
                token = []
                backslashes = 0
                while i < length:
                    ch = s[i]
                    if ch == '\\':
                        backslashes += 1
                        i += 1
                        continue
                    if ch == '"' and backslashes % 2 == 0:
                        # End of quoted part
                        token.append('\\' * (backslashes // 2))
                        i += 1
                        break
                    else:
                        token.append('\\' * (backslashes // 2))
                        token.append(ch)
                        backslashes = 0
                        i += 1
                else:
                    # Unterminated quote - treat rest as part of token
                    pass
                args.append(''.join(token))
                # After a quoted token, continue to next token
            else:
                token = []
                while i < length and not s[i].isspace():
                    token.append(s[i])
                    i += 1
                args.append(''.join(token))
    return args

