def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    import uuid

    # Resolve and validate archive path
    archive_path = os.path.abspath(str(archive_path))
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive file does not exist: {archive_path}")

    # Resolve temporary path
    tmp_path = os.path.expanduser(str(tmp_path))
    if not os.path.isdir(tmp_path):
        os.makedirs(tmp_path, mode=0o700, exist_ok=True)

    # Decide on directory name for extraction
    if filename:
        repo_dir_name = filename.strip()
    else:
        base_name = os.path.basename(archive_path)
        # Strip common extensions
        for ext in ('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar', '.zip'):
            if base_name.endswith(ext):
                base_name = base_name[: -len(ext)]
                break
        repo_dir_name = base_name or uuid.uuid4().hex

    repo_dir = os.path.join(tmp_path, repo_dir_name)

    if os.path.exists(repo_dir):
        raise FileExistsError(f"Extraction target already exists: {repo_dir}")

    os.makedirs(repo_dir, mode=0o700)

    # Determine extraction command based on file type
    if archive_path.endswith(('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar')):
        cmd = ['tar', '-xf', archive_path, '-C', repo_dir]
    elif archive_path.endswith('.zip'):
        cmd = ['unzip', '-q', archive_path, '-d', repo_dir]
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        # Clean up partially extracted files
        if os.path.isdir(repo_dir):
            try:
                import shutil
                shutil.rmtree(repo_dir)
            except Exception:
                pass
        raise OSError(f"Extraction failed for {archive_path}: {exc}") from exc

    return f"file://{os.path.abspath(repo_dir)}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Validate input types
    if not isinstance(archive_path, str):
        raise TypeError(f"archive_path must be a str, got {type(archive_path).__name__}")
    if not os.path.isfile(archive_path):
        raise FileNotFoundError(f"Archive file does not exist: {archive_path}")

    # Resolve temporary path
    tmp_dir = str(tmp_path)
    try:
        os.makedirs(tmp_dir, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create temporary directory '{tmp_dir}': {exc}") from exc

    # Determine destination directory name
    if filename is None:
        base = os.path.basename(archive_path)
        # Strip common archive suffixes
        suffixes = [
            ".tar.gz", ".tgz",
            ".tar.bz2", ".tbz2",
            ".tar.xz", ".txz",
            ".zip", ".tar", ".gz", ".bz2", ".xz"
        ]
        lowered = base.lower()
        for sfx in suffixes:
            if lowered.endswith(sfx):
                base = base[: -len(sfx)]
                break
        filename = base
    dest_dir = os.path.join(tmp_dir, filename)

    if os.path.exists(dest_dir):
        raise FileExistsError(f"Destination directory already exists: {dest_dir}")

    try:
        os.makedirs(dest_dir, exist_ok=False)
    except Exception as exc:
        raise OSError(f"Could not create extraction directory '{dest_dir}': {exc}") from exc

    # Unpack the archive using the standard library
    try:
        shutil.unpack_archive(archive_path, dest_dir)
    except Exception as exc:
        try:
            shutil.rmtree(dest_dir, ignore_errors=True)
        except Exception:
            pass
        raise RuntimeError(f"Failed to unpack archive '{archive_path}': {exc}") from exc

    return f"file://{os.path.abspath(dest_dir)}"

