def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern.
    If `pattern` is a string, it is compiled with re.compile.
    If `strip` is True, leading and trailing whitespace is removed before compilation.
    If `pattern` is already a compiled regex object, it is returned unchanged.
    Raises TypeError for unsupported types.
    """
    # Determine the compiled regex type for compatibility across Python versions
    try:
        compiled_type = re.Pattern  # Python 3.7+
    except AttributeError:
        compiled_type = re._pattern_type

    if pattern is None:
        return None

    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    if isinstance(pattern, compiled_type):
        return pattern

    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

