def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mu = 0.2
    sigma = 0.1
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input must be numeric array or scalar.") from e
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = -((x_arr - mu) ** 2) / (2 * sigma ** 2)
    return coeff * np.exp(exponent)

