            # Detect and parse based on file extension
            if fname.lower().endswith('.toml'):
                import toml
                cfg = toml.loads(raw_data)
            elif fname.lower().endswith(('.yaml', '.yml')):
                import yaml
                cfg = yaml.safe_load(raw_data)
            elif fname.lower().endswith('.json'):
                import json
                cfg = json.loads(raw_data)
            else:
                raise ValueError(f'Unsupported file extension for {fname}')

            # Resolve environment variables if requested
            if resolve_env:
                import os

                def _expand(obj):
                    if isinstance(obj, str):
                        return os.path.expandvars(obj)
                    if isinstance(obj, dict):
                        return {k: _expand(v) for k, v in obj.items()}
                    if isinstance(obj, list):
                        return [_expand(x) for x in obj]
                    return obj

                cfg = _expand(cfg)

            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                cfg.update(overrides)

            config_map[fname] = cfg

        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=True
            )
            error_records.append(record)
            config_map[fname] = None

    return config_map, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml
    import logging
    import re

    def _resolve_env_in_dict(d):
        """Recursively replace ${VAR} or ${VAR:default} in string values with environment variables."""
        pattern = re.compile(r'\$\{(?P<var>[A-Za-z0-9_]+)(?::(?P<default>[^}]*))?\}')
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(v) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(v) for v in d]
        elif isinstance(d, str):
            def repl(match):
                var = match.group('var')
                default = match.group('default')
                return os.getenv(var, default if default is not None else '')
            return pattern.sub(repl, d)
        else:
            return d

    def _merge_dict_recursive(target, overrides_dict):
        """Deep merge overrides_dict into target."""
        for key, value in overrides_dict.items():
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                _merge_dict_recursive(target[key], value)
            else:
                target[key] = value
        return target

    configs = {}
    errors = []

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"Config file not found: {filename}")
            with open(filename, 'r') as f:
                content = f.read()
            ext = os.path.splitext(filename)[1].lower()
            if ext == '.json':
                config = json.loads(content)
            elif ext in ('.yaml', '.yml'):
                config = yaml.safe_load(content)
            elif ext == '.toml':
                config = toml.loads(content)
            else:
                raise ValueError(f"Unsupported config file extension: {ext}")
        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=exc
            )
            errors.append(record)
            continue

        if not isinstance(config, dict):
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Top-level config is not a dictionary: {filename}",
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        if resolve_env:
            try:
                config = _resolve_env_in_dict(config)
            except Exception as exc:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f"Environment variable resolution error: {exc}",
                    args=(),
                    exc_info=exc
                )
                errors.append(record)
                continue

        if overrides:
            try:
                _merge_dict_recursive(config, overrides)
            except Exception as exc:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f"Error applying overrides: {exc}",
                    args=(),
                    exc_info=exc
                )
                errors.append(record)
                continue

        configs[filename] = config

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed
    configuration, and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    error_records = []
    logger_name = 'config_loader'
    log = logging.getLogger(logger_name)

    def _process_env(value):
        """Recursively expand environment variables in strings."""
        if isinstance(value, str):
            # expandenv on the string
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _process_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_process_env(v) for v in value]
        elif isinstance(value, tuple):
            return tuple(_process_env(v) for v in value)
        else:
            return value

    # Ensure we have an iterable
    if isinstance(config_filenames, str):
        config_filenames = [config_filenames]
    for filename in config_filenames:
        try:
            with open(filename, 'r') as fp:
                raw = fp.read()
        except Exception as e:
            rec = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to read file: {e}",
                args=(),
                exc_info=None
            )
            error_records.append(rec)
            continue

        parsed = None
        try:
            if filename.endswith('.yaml') or filename.endswith('.yml'):
                parsed = yaml.safe_load(raw)
            elif filename.endswith('.toml'):
                parsed = toml.loads(raw)
            elif filename.endswith('.json'):
                parsed = json.loads(raw)
            else:
                # Unsupported format
                raise ValueError(f"Unsupported configuration file format: {filename}")
        except Exception as e:
            rec = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to parse configuration: {e}",
                args=(),
                exc_info=None
            )
            error_records.append(rec)
            continue

        if parsed is None:
            rec = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Parsed configuration is empty or None for file: {filename}",
                args=(),
                exc_info=None
            )
            error_records.append(rec)
            continue

        # Optional overrides
        if overrides:
            if isinstance(parsed, dict) and isinstance(overrides, dict):
                parsed.update(overrides)
            else:
                rec = logging.LogRecord(
                    name=logger_name,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg="Overrides must be a dict compatible with the parsed configuration",
                    args=(),
                    exc_info=None
                )
                error_records.append(rec)

        # Resolve environment variables if requested
        if resolve_env:
            parsed = _process_env(parsed)

        configs[filename] = parsed

    return configs, error_records

