def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        # Gather all handler classes defined on this class that specify a
        # protocol version. Handlers may expose the version via an attribute
        # named either `_protocol_version` or `protocol_version`.
        handlers = {}
        for name, obj in vars(cls).items():
            if isinstance(obj, type):
                # Detect the version attribute
                if hasattr(obj, "_protocol_version"):
                    ver = getattr(obj, "_protocol_version")
                elif hasattr(obj, "protocol_version"):
                    ver = getattr(obj, "protocol_version")
                else:
                    continue

                if not isinstance(ver, tuple):
                    # Not a valid version specification; skip
                    continue

                # Ensure no duplicate version entries
                if ver in handlers:
                    msg = (
                        f"Duplicate handler for protocol version {ver} detected "
                        f"in attribute '{name}'. Only one handler per version "
                        "is allowed."
                    )
                    raise ValueError(msg)

                handlers[ver] = obj

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple of integers, got {type(protocol_version).__name__}"
                )

            # Return either an empty dict or a single-item dict
            return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

        return handlers

